const j = $input.first().json || {};
const apiBase = j.CONFIG?.lulu?.apiBase || '';
const env = /sandbox/.test(apiBase) ? 'SANDBOX' : (apiBase ? 'PRODUCTION' : 'UNKNOWN');
let submitPath = 'UNKNOWN';
if (j.__skipLulu) submitPath = 'IDEMPOTENT-SKIP';
else if (j.luluAccessToken && env==='SANDBOX') submitPath = 'SANDBOX - BEARER';
else if (j.luluAccessToken && env==='PRODUCTION') submitPath = 'PRODUCTION - BEARER';
else submitPath = 'PRODUCTION - BASIC';
const banner = {
  env,
  apiBase,
  submitPath,
  tokenIssuedAt: j.luluTokenIssuedAt || null,
  tokenExpiresIn: j.luluTokenExpiresIn || null,
  orderId: j.orderId,
  timestamp: new Date().toISOString()
};
console.log('W4 Status Banner →', banner);
return [{ json: { ...j, _statusBanner: banner } }];

// Merge the PDFMonkey response with the preserved workflow context
const httpResp = $input.first().json || {};
let ctx = {};
try { ctx = ($items('Build Pages HTML (8.75in)', 0, $runIndex)?.[0]?.json) || {}; } catch {}
if (!ctx.orderId) {
  try { ctx = ($items('Validate & Normalize W4 Input', 0, $runIndex)?.[0]?.json) || ctx; } catch {}
}

// Keep the top-level shape that Poll node expects (document/data)
const docObj = httpResp.document || httpResp.data || httpResp;
return [{
  json: {
    ...ctx,
    document: docObj
  }
}];
